183	
184	            $query->where(fn ($q) => $q->whereNull($teamsKey)
185	                ->orWhere($teamsKey, $params[$teamsKey] ?? getPermissionsTeamId())
186	            );
187	            unset($params[$teamsKey]);
188	        }
