        $this->collectModels($models, $modelClass)
            ->groupBy(fn (Model $model) => $model::class)
            ->each(function (Collection $group, string $class) {
                $ids = $group->map(fn (Model $model) => $model->getKey())->all();

                $this->assignedModels($class)->detach($ids);
